    n = len(arr)
    if n == 0:
        return 0
    low, high = 0, n - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    return low

def is_Perfect_Square(n):
    if n < 0:
        return False
    x = n
    while x * x > n:
        x = (x + n // x) // 2
    return x * x == n

def is_Perfect_Square(n):
    low, high = 0, n
    while low <= high:
        mid = (low + high) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            low = mid + 1
        else:
            high = mid - 1
    return False

